import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getEmpresas, criarEmpresa, atualizarEmpresa, removerEmpresa, bloquearEmpresa, atenderSolicitacaoDominio, recusarSolicitacaoDominio, getPlataformaConfig, getUsuarios } from '../../services/adminService';
import { getAssinaturas } from '../../services/planosService';
import { useLocalMode, LocalModeBanner, LicencaBloqueadaBanner } from '../../contexts/LocalModeContext';
import AdminHeader from '../../components/admin/AdminHeader';

const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);

const Modal = ({ empresa, comissaoPadrao, onClose, onSave }) => {
  const [form, setForm] = useState({
    name: empresa?.name ?? '',
    address: empresa?.address ?? '',
    comissao_pct: empresa?.comissao_pct ?? null,
    user_id: empresa?.user_id ?? '',
    modulo_delivery: empresa?.modulo_delivery ?? true,
    modulo_salao: empresa?.modulo_salao ?? false,
    modulo_gdoor: empresa?.modulo_gdoor ?? false,
    modulo_favicon_personalizado: empresa?.modulo_favicon_personalizado ?? false,
  });
  const [salvando, setSalvando] = useState(false);
  const usaPadraoGlobal = form.comissao_pct === null;

  // Donos disponíveis pro select: qualquer usuário (menos admin) que ainda
  // não tem restaurante vinculado, mais o dono atual dessa empresa (senão a
  // opção selecionada some do select ao editar). Evita expor UUID cru — o
  // admin escolhe pelo nome/email, o mesmo poder de antes (promove pra
  // restaurant_owner ao salvar), só que sem precisar saber/colar o UUID.
  const [usuarios, setUsuarios] = useState(null);
  useEffect(() => {
    getUsuarios({ limit: 1000 })
      .then((d) => setUsuarios(d.usuarios ?? []))
      .catch(() => setUsuarios([]));
  }, []);
  const donosDisponiveis = (usuarios ?? [])
    .filter((u) => u.role !== 'admin' && (!u.restaurante || u.restaurante.id === empresa?.id))
    .sort((a, b) => (a.name ?? '').localeCompare(b.name ?? '', 'pt-BR'));
  // Fallback defensivo: se o user_id atual não aparecer na lista (ex: conta
  // apagada), mantém a opção visível em vez de sumir silenciosamente o valor.
  const donoAtualPerdido = form.user_id && usuarios && !donosDisponiveis.some((u) => u.id === form.user_id);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSalvando(true);
    try {
      if (empresa) {
        await atualizarEmpresa(empresa.id, form);
      } else {
        await criarEmpresa(form);
      }
      onSave();
    } catch (err) {
      alert(err.message);
    } finally {
      setSalvando(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white dark:bg-zinc-800 rounded-xl w-full max-w-md max-h-[90vh] overflow-y-auto p-6">
        <h3 className="text-lg font-semibold mb-4 text-gray-900 dark:text-zinc-100">{empresa ? 'Editar Empresa' : 'Nova Empresa'}</h3>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Nome *</label>
            <input
              required
              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Endereço</label>
            <input
              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={form.address}
              onChange={(e) => setForm({ ...form, address: e.target.value })}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Comissão plataforma (%)</label>
            <input
              type="number"
              min="0"
              max="100"
              step="0.5"
              disabled={usaPadraoGlobal}
              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-50 dark:disabled:bg-zinc-800 disabled:text-gray-400 dark:disabled:text-zinc-500"
              value={usaPadraoGlobal ? '' : form.comissao_pct}
              placeholder={usaPadraoGlobal ? `${comissaoPadrao}%` : ''}
              onChange={(e) => setForm({ ...form, comissao_pct: parseFloat(e.target.value) })}
            />
            <label className="flex items-center gap-2 mt-2 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={usaPadraoGlobal}
                onChange={(e) => setForm({ ...form, comissao_pct: e.target.checked ? null : comissaoPadrao })}
                className="w-4 h-4 rounded accent-blue-600"
              />
              <span className="text-xs text-gray-500 dark:text-zinc-400">
                Usar padrão global da plataforma ({comissaoPadrao}%)
              </span>
            </label>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">
              Dono (restaurant_owner)
            </label>
            <select
              disabled={!usuarios}
              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
              value={form.user_id}
              onChange={(e) => setForm({ ...form, user_id: e.target.value })}
            >
              <option value="">— Sem dono ainda —</option>
              {donoAtualPerdido && (
                <option value={form.user_id}>{form.user_id} (conta não encontrada)</option>
              )}
              {donosDisponiveis.map((u) => (
                <option key={u.id} value={u.id}>{u.name}</option>
              ))}
            </select>
            <p className="text-xs text-gray-400 dark:text-zinc-500 mt-1">
              {usuarios ? 'Só aparecem contas sem restaurante vinculado ainda. Vincular promove a conta pra restaurant_owner.' : 'Carregando usuários...'}
            </p>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-2">Módulos liberados</label>
            <div className="flex flex-col gap-2">
              <label className="flex items-center gap-2 text-sm text-gray-700 dark:text-zinc-300">
                <input
                  type="checkbox"
                  checked={form.modulo_delivery}
                  onChange={(e) => setForm({ ...form, modulo_delivery: e.target.checked })}
                />
                Delivery
              </label>
              <label className="flex items-center gap-2 text-sm text-gray-700 dark:text-zinc-300">
                <input

