1	// components/ui/Select.jsx - Shadcn style Select
2	import React, { useState } from "react";
3	import { ChevronDown, Check, Search, X } from "lucide-react";
4	import { cn } from "../../utils/cn";
5	import Button from "./Button";
6	import Input from "./Input";
7	
8	const Select = React.forwardRef(({
9	    className,
10	    options = [],
11	    value,
12	    defaultValue,
13	    placeholder = "Select an option",
14	    multiple = false,
15	    disabled = false,
16	    required = false,
17	    label,
18	    description,
19	    error,
20	    searchable = false,
21	    clearable = false,
22	    loading = false,
23	    id,
24	    name,
25	    onChange,
26	    onOpenChange,
27	    ...props
28	}, ref) => {
29	    const [isOpen, setIsOpen] = useState(false);
30	    const [searchTerm, setSearchTerm] = useState("");
31	
32	    // Generate unique ID if not provided
33	    const selectId = id || `select-${Math.random()?.toString(36)?.substr(2, 9)}`;
34	
35	    // Filter options based on search
36	    const filteredOptions = searchable && searchTerm
37	        ? options?.filter(option =>
38	            option?.label?.toLowerCase()?.includes(searchTerm?.toLowerCase()) ||
39	            (option?.value && option?.value?.toString()?.toLowerCase()?.includes(searchTerm?.toLowerCase()))
40	        )
41	        : options;
42	
43	    // Get selected option(s) for display
44	    const getSelectedDisplay = () => {
45	        if (!value) return placeholder;
46	
47	        if (multiple) {
48	            const selectedOptions = options?.filter(opt => value?.includes(opt?.value));
49	            if (selectedOptions?.length === 0) return placeholder;
50	            if (selectedOptions?.length === 1) return selectedOptions?.[0]?.label;
51	            return `${selectedOptions?.length} items selected`;
52	        }
53	
54	        const selectedOption = options?.find(opt => opt?.value === value);
55	        return selectedOption ? selectedOption?.label : placeholder;
56	    };
57	
58	    const handleToggle = () => {
59	        if (!disabled) {
60	            const newIsOpen = !isOpen;
61	            setIsOpen(newIsOpen);
62	            onOpenChange?.(newIsOpen);
63	            if (!newIsOpen) {
64	                setSearchTerm("");
65	            }
66	        }
67	    };
68	
69	    const handleOptionSelect = (option) => {
70	        if (multiple) {
71	            const newValue = value || [];
72	            const updatedValue = newValue?.includes(option?.value)
73	                ? newValue?.filter(v => v !== option?.value)
74	                : [...newValue, option?.value];
75	            onChange?.(updatedValue);
76	        } else {
77	            onChange?.(option?.value);
78	            setIsOpen(false);
79	            onOpenChange?.(false);
80	        }
81	    };
82	
83	    const handleClear = (e) => {
84	        e?.stopPropagation();
85	        onChange?.(multiple ? [] : '');
86	    };
87	
88	    const handleSearchChange = (e) => {
89	        setSearchTerm(e?.target?.value);
90	    };
91	
92	    const isSelected = (optionValue) => {
93	        if (multiple) {
94	            return value?.includes(optionValue) || false;
95	        }
96	        return value === optionValue;
97	    };
98	
99	    const hasValue = multiple ? value?.length > 0 : value !== undefined && value !== '';
100	
101	    return (
102	        <div className={cn("relative", className)}>
103	            {label && (
104	                <label
105	                    htmlFor={selectId}
106	                    className={cn(
107	                        "text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 mb-2 block",
108	                        error ? "text-destructive" : "text-foreground"
109	                    )}
110	                >
111	                    {label}
112	                    {required && <span className="text-destructive ml-1">*</span>}
113	                </label>
114	            )}
115	            <div className="relative">
116	                <button
117	                    ref={ref}
118	                    id={selectId}
119	                    type="button"
120	                    className={cn(
121	                        "flex h-10 w-full items-center justify-between rounded-md border border-input bg-white text-black px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
122	                        error && "border-destructive focus:ring-destructive",
123	                        !hasValue && "text-muted-foreground"
124	                    )}
125	                    onClick={handleToggle}
126	                    disabled={disabled}
127	                    aria-expanded={isOpen}
128	                    aria-haspopup="listbox"
129	                    {...props}
130	                >
131	                    <span className="truncate">{getSelectedDisplay()}</span>
132	
133	                    <div className="flex items-center gap-1">
134	                        {loading && (
135	                            <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24">
136	                                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
137	                                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
138	                            </svg>
139	                        )}
140	
141	                        {clearable && hasValue && !loading && (
142	                            <Button
143	                                variant="ghost"
144	                                size="icon"
145	                                className="h-4 w-4"
146	                                onClick={handleClear}
147	                            >
148	                                <X className="h-3 w-3" />
149	                            </Button>
150	                        )}
151	
152	                        <ChevronDown className={cn("h-4 w-4 transition-transform", isOpen && "rotate-180")} />
153	                    </div>
154	                </button>
155	
156	                {/* Hidden native select for form submission */}
157	                <select
158	                    name={name}
159	                    value={value || ''}
160	                    onChange={() => { }} // Controlled by our custom logic
161	                    className="sr-only"
162	                    tabIndex={-1}
163	                    multiple={multiple}
164	                    required={required}
165	                >
166	                    <option value="">Select...</option>
167	                    {options?.map(option => (
168	                        <option key={option?.value} value={option?.value}>
169	                            {option?.label}
170	                        </option>
171	                    ))}
172	                </select>
173	
174	                {/* Dropdown */}
175	                {isOpen && (
176	                    <div className="absolute z-50 w-full mt-1 bg-white text-black border border-border rounded-md shadow-md">
177	                        {searchable && (
178	                            <div className="p-2 border-b">
179	                                <div className="relative">
180	                                    <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
181	                                    <Input
182	                                        placeholder="Search options..."
183	                                        value={searchTerm}
184	                                        onChange={handleSearchChange}
185	                                        className="pl-8"
186	                                    />
187	                                </div>
188	                            </div>
189	                        )}
190	
191	                        <div className="py-1 max-h-60 overflow-auto">
192	                            {filteredOptions?.length === 0 ? (
193	                                <div className="px-3 py-2 text-sm text-muted-foreground">
194	                                    {searchTerm ? 'No options found' : 'No options available'}
195	                                </div>
196	                            ) : (
197	                                filteredOptions?.map((option) => (
198	                                    <div
199	                                        key={option?.value}
200	                                        className={cn(
201	                                            "relative flex cursor-pointer select-none items-center rounded-sm px-3 py-2 text-sm outline-none hover:bg-accent hover:text-accent-foreground",
202	                                            isSelected(option?.value) && "bg-primary text-primary-foreground",
203	                                            option?.disabled && "pointer-events-none opacity-50"
204	                                        )}
205	                                        onClick={() => !option?.disabled && handleOptionSelect(option)}
206	                                    >
207	                                        <span className="flex-1">{option?.label}</span>
208	                                        {multiple && isSelected(option?.value) && (
209	                                            <Check className="h-4 w-4" />
210	                                        )}
211	                                        {option?.description && (
212	                                            <span className="text-xs text-muted-foreground ml-2">
213	                                                {option?.description}
214	                                            </span>
215	                                        )}
216	                                    </div>
217	                                ))
218	                            )}
219	                        </div>
220	                    </div>
