1	import React, { useState, useEffect, useCallback } from 'react';
2	import {
3	  getUsuarios, trocarCredenciaisUsuario, getEmpresas, atualizarEmpresa,
4	  editarUsuario, bloquearUsuario, excluirUsuario, liberarBloqueioLoginUsuario,
5	} from '../../services/adminService';
6	import AdminHeader from '../../components/admin/AdminHeader';
7	import { useAuth } from '../../contexts/AuthContext';
8	import { formatDuracao } from '../../utils/formatDuracao';
9	
10	// Badge com contagem regressiva do bloqueio por tentativas de senha erradas no login
11	// principal — próprio componente pra ticar a cada segundo sem re-renderizar a tabela
12	// inteira de usuários.
13	const BloqueioLoginBadge = ({ bloqueadoAte }) => {
14	  const [now, setNow] = useState(Date.now());
15	  const bloqueadoAteMs = new Date(bloqueadoAte).getTime();
16	
17	  useEffect(() => {
18	    const interval = setInterval(() => setNow(Date.now()), 1000);
19	    return () => clearInterval(interval);
20	  }, []);
21	
22	  if (bloqueadoAteMs <= now) return null;
23	
24	  return (
25	    <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 dark:bg-red-950/40 text-red-700 dark:text-red-400 font-mono">
26	      Bloqueado (login) · {formatDuracao(bloqueadoAteMs - now)}
27	    </span>
28	  );
29	};
30	
31	const ROLE_LABELS = {
32	  admin: 'Admin',
33	  restaurant_owner: 'Dono de restaurante',
34	  customer: 'Cliente',
35	  motoboy: 'Motoboy',
36	};
37	
