40	  restaurant_owner: 'bg-blue-100 dark:bg-blue-950/40 text-blue-700 dark:text-blue-400',
41	  customer: 'bg-gray-100 dark:bg-zinc-700 text-gray-600 dark:text-zinc-300',
42	  motoboy: 'bg-amber-100 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400',
43	};
44	
45	const VincularModal = ({ usuario, empresas, onClose, onSave }) => {
46	  const [restaurantId, setRestaurantId] = useState(usuario.restaurante?.id ?? '');
47	  const [salvando, setSalvando] = useState(false);
48	  const [erro, setErro] = useState(null);
49	
50	  const handleSubmit = async (e) => {
51	    e.preventDefault();
52	    if (!restaurantId) return;
53	    setSalvando(true);
54	    setErro(null);
55	    try {
56	      await atualizarEmpresa(restaurantId, { user_id: usuario.id });
57	      onSave();
58	    } catch (err) {
59	      setErro(err.message);
60	    } finally {
61	      setSalvando(false);
62	    }
63	  };
64	
65	  return (
66	    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
67	      <div className="bg-white dark:bg-zinc-800 rounded-xl w-full max-w-md p-6">
68	        <h3 className="text-lg font-semibold mb-1 text-gray-900 dark:text-zinc-100">Vincular a restaurante</h3>
69	        <p className="text-sm text-gray-500 dark:text-zinc-400 mb-4">{usuario.name || usuario.email}</p>
70	        <form onSubmit={handleSubmit} className="space-y-4">
71	          <div>
72	            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Restaurante</label>
73	            <select
74	              required
75	              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
76	              value={restaurantId}
77	              onChange={(e) => setRestaurantId(e.target.value)}
78	            >
79	              <option value="" disabled>Selecione...</option>
80	              {empresas.map((e) => (
81	                <option key={e.id} value={e.id}>{e.name}{e.user_id && e.user_id !== usuario.id ? ' (já tem dono)' : ''}</option>
82	              ))}
83	            </select>
84	          </div>
85	
86	          {erro && <p className="text-sm text-red-600 dark:text-red-400">{erro}</p>}
87	
88	          <div className="flex gap-3 pt-2">
89	            <button type="button" onClick={onClose}
90	              className="flex-1 px-4 py-2 border border-gray-300 dark:border-zinc-700 rounded-lg text-sm font-medium text-gray-700 dark:text-zinc-300 hover:bg-gray-50 dark:hover:bg-zinc-700">
91	              Cancelar
92	            </button>
93	            <button type="submit" disabled={salvando}
94	              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50">
95	              {salvando ? 'Salvando...' : 'Vincular'}
96	            </button>
97	          </div>
98	        </form>
99	      </div>
100	    </div>
101	  );
102	};
103	
104	const CredenciaisModal = ({ usuario, onClose, onSave }) => {
105	  const [email, setEmail] = useState('');
106	  const [senha, setSenha] = useState('');
107	  const [salvando, setSalvando] = useState(false);
108	  const [erro, setErro] = useState(null);
109	
110	  const handleSubmit = async (e) => {
111	    e.preventDefault();
112	    if (!email && !senha) {
113	      setErro('Informe email e/ou senha.');
114	      return;
115	    }
116	    if (senha && senha.length < 8) {
117	      setErro('Senha deve ter no mínimo 8 caracteres.');
118	      return;
119	    }
120	    setSalvando(true);
121	    setErro(null);
122	    try {
123	      await trocarCredenciaisUsuario(usuario.id, {
124	        email: email.trim() || undefined,
125	        senha: senha || undefined,
126	      });
127	      onSave();
128	    } catch (err) {
