149	              value={email}
150	              onChange={(e) => setEmail(e.target.value)}
151	            />
152	          </div>
153	          <div>
154	            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Nova senha</label>
155	            <input
156	              type="password"
157	              minLength={8}
158	              placeholder="Deixe em branco pra não trocar"
159	              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
160	              value={senha}
161	              onChange={(e) => setSenha(e.target.value)}
162	            />
163	          </div>
164	
165	          {erro && <p className="text-sm text-red-600 dark:text-red-400">{erro}</p>}
166	
167	          <div className="flex gap-3 pt-2">
168	            <button type="button" onClick={onClose}
169	              className="flex-1 px-4 py-2 border border-gray-300 dark:border-zinc-700 rounded-lg text-sm font-medium text-gray-700 dark:text-zinc-300 hover:bg-gray-50 dark:hover:bg-zinc-700">
170	              Cancelar
171	            </button>
172	            <button type="submit" disabled={salvando}
173	              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50">
174	              {salvando ? 'Salvando...' : 'Salvar'}
