252	          </div>
253	        </form>
254	      </div>
255	    </div>
256	  );
257	};
258	
259	const LIMIT = 50;
260	
261	const AdminUsuarios = () => {
262	  const { user } = useAuth();
263	  const [usuarios, setUsuarios] = useState([]);
264	  const [total, setTotal] = useState(0);
265	  const [page, setPage] = useState(1);
266	  const [busca, setBusca] = useState('');
267	  const [role, setRole] = useState('');
