322	    } catch (e) {
323	      alert(e.message);
324	    } finally {
325	      setProcessando(null);
326	    }
327	  };
328	
329	  const handleExcluir = async (usuario) => {
330	    if (!confirm(`Excluir "${usuario.name || usuario.email}" permanentemente? Essa ação não pode ser desfeita.`)) return;
331	    setProcessando(usuario.id);
