341	
342	  const totalPages = Math.max(1, Math.ceil(total / LIMIT));
343	
344	  return (
345	    <div className="min-h-screen bg-gray-50 dark:bg-zinc-900">
346	      <AdminHeader active="/admin/usuarios" title="Painel Dev-Admin" subtitle="Gestão de Usuários" />
347	
348	      <main className="p-6 max-w-6xl mx-auto">
349	        <div className="flex items-center justify-between mb-6 flex-wrap gap-3">
350	          <h2 className="text-lg font-semibold text-gray-900 dark:text-zinc-100">
