352	          </h2>
353	          <div className="flex gap-2">
354	            <input
355	              placeholder="Buscar por nome ou email..."
356	              className="border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500 w-56"
357	              value={busca}
